INSERT INTO `produks` (`id`, `nama_produk`, `harga`, `stok`, `kategori`, `deskripsi`, `foto`, `gambar`, `created_at`, `updated_at`) VALUES
(2, 'vas  bunga', 400000.00, 28, 'interior desain', '\"Ubah sudut ruanganmu jadi lebih hidup dan penuh estetika dengan Vas Bunga Premium dari [Nama Toko]! 🏺✨Dirancang dengan sentuhan desain minimalis modern, vas bunga ini tidak hanya berfungsi sebagai wadah bunga, tetapi juga sebagai karya seni mandiri yang mempercantik rumah Anda. Cocok ditempatkan di meja tamu, meja kerja, maupun rak pajangan.', 'https://down-id.img.susercontent.com/file/26390697e0c8720cc0903fa042598828', NULL, '2026-08-23 23:52:11', '2026-08-27 20:29:47'),
(3, 'boneka', 45000.00, 99, 'mainan', '\"Cari kado yang berkesan atau teman peluk yang super nyaman? Boneka Premium dari [Nama Toko] adalah jawabannya! 🧸✨Dibuat dengan bahan bulu halus berkualitas tinggi yang tidak mudah rontok dan isian yang sangat empuk, boneka ini siap memberikan kehangatan setiap hari. Desainnya yang super cute dan aesthetic juga sangat cocok untuk mempercantik sudut kamar tidur atau ruang tamu Anda.', 'https://down-id.img.susercontent.com/file/id-11134207-7r98o-llqta2vzerrzc7', NULL, '2026-08-25 23:02:23', '2026-08-27 20:19:15'),
(5, 'tolak angin', 6000.00, 12997, 'obat herbal', 'Tolak Angin merupakan ramuan herbal alami terpercaya warisan leluhur yang diproses menggunakan teknologi modern berstandar internasional. Obat cair dalam kemasan saset ini praktis dibawa ke mana saja, sangat cocok dikonsumsi saat tubuh mulai terasa lelah, kurang tidur, atau terserang cuaca tidak menentu.', 'https://d3bbrrd0qs69m4.cloudfront.net/images/product/apotek_online_k24klik_2025032103101223085_tolak-angin-plus-madu.jpg', NULL, '2026-08-25 23:31:54', '2026-09-06 21:19:45'),
(6, 'make up MAKE OVER', 250000.00, 98, 'KOSMETIK', 'Flawless Glow Cushion SPF 30 PA++ Tampilkan kulit wajah yang sehat, mulus, dan glowing seketika dengan Flawless Glow Cushion.Produk ini dirancang khusus untuk memberikan hasil akhir yang natural namun mampu menutupi ketidaksempurnaan wajah seperti noda hitam dan bekas jerawat secara optimal. Memiliki formula yang ringan di kulit, sangat nyaman digunakan sehari-hari tanpa terasa berat atau membuat pori-pori tersumbat.', 'https://i.pinimg.com/originals/f8/45/45/f845450f907b2aa6aa05357a66664c60.png', NULL, '2026-08-27 17:22:44', '2026-08-27 19:50:16');
